INSERT INTO `config_info` VALUES (1, 'application.yaml', 'DEFAULT_GROUP', 'spring:\n  cloud:\n    sentinel:\n      eager: true\n      transport:\n        dashboard: ${SENTINEL_DASHBOARD_HOST}:${SENTINEL_DASHBOARD_PORT}\n        port: ${SENTINEL_TRANSPORT_PORT}\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://${MYSQL_HOST}:${MYSQL_PORT}/${MYSQL_DATABASE}?rewriteBatchedStatements=true&characterEncoding=UTF-8&autoReconnect=true&failOverReadOnly=false&serverTimezone=Asia/Shanghai&allowMultiQueries=true\n    username: ${MYSQL_USERNAME}\n    password: ${MYSQL_PASSWORD}\n\n  data:\n    redis:\n      port: ${REDIS_PORT}\n      host: ${REDIS_HOST}\n      password: ${REDIS_PASSWORD}\n      database: 0\n      timeout: 6000ms\n      lettuce:\n        pool:\n          max-active: 8\n          max-wait: -1ms\n          max-idle: 8\n          min-idle: 0\n\n  cache:\n    type: redis\n    redis:\n      time-to-live: 1800000\n      cache-null-values: true\n      use-key-prefix: true\n      key-prefix: SapientiaCloud-EduPivot\n    caffeine:\n      spec: maximumSize=500,expireAfterWrite=10m\n\nfeign:\n  sentinel:\n    enabled: true\n\nknife4j:\n  enable: true\n  basic:\n    enable: true\n    username: ${KNIFE4J_USERNAME}\n    password: ${KNIFE4J_PASSWORD}\n\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: health,info,sentinel\n  tracing:\n    enabled: true\n    sampling:\n      probability: 1.0\n  zipkin:\n    tracing:\n      endpoint: http://localhost:9411/api/v2/spans\n\nlogging:\n  level:\n    root: INFO\n    com.dayz: INFO\n\n\nMYSQL_HOST: 127.0.0.1\nMYSQL_PORT: 3306\nMYSQL_USERNAME: root\nMYSQL_PASSWORD: zhaosheng123\nMYSQL_DATABASE: sapientiacloud_edupivot\nREDIS_HOST: 127.0.0.1\nREDIS_PORT: 6379\nREDIS_USERNAME:\nREDIS_PASSWORD: zhaosheng123\nKNIFE4J_USERNAME: admin\nKNIFE4J_PASSWORD: zhaosheng123\nSENTINEL_DASHBOARD_HOST: 127.0.0.1\nSENTINEL_DASHBOARD_PORT: 8858\nSENTINEL_TRANSPORT_PORT: 8719\n', 'c6e396803bb3e7783a53ec830bea9674', '2025-08-04 23:56:52', '2026-04-24 16:36:09', 'nacos', '27.189.42.3', '', '', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` VALUES (2, 'SapientiaCloud-EduPivot--auth.yaml', 'DEFAULT_GROUP', 'feign:\n  client:\n    config:\n      default:\n        connectTimeout: 5000\n        readTimeout: 5000\n        loggerLevel: full\n\nspring:\n  jpa:\n    open-in-view: false\n  security:\n    oauth2:\n      client:\n        registration:\n          github:\n            client-id: ${GITHUB_CLIENT_ID}\n            client-secret: ${GITHUB_CLIENT_SECRET}\n            redirect-uri: https://edupivot.xyz/auth/oauth2/callback/github\n            scope: \n              - user:email\n              - read:user\n        provider:\n          github:\n            authorization-uri: https://github.com/login/oauth/authorize\n            token-uri: https://api.edupivot.xyz/login/oauth/access_token\n            user-info-uri: https://api.edupivot.xyz/user\n            user-name-attribute: login\napp:\n  http:\n    proxy:\n      enabled: false\n      host: ${PROXY_HOST}\n      port: ${PROXY_PORT}\n\nGITHUB_CLIENT_ID: Ov23lifIKc7byE3a1RCu\nGITHUB_CLIENT_SECRET: 81b20fb6dbcdc9f44ccbcbca39d971a56aed798f\nPROXY_HOST: 117.72.194.197\nPROXY_PORT: 7890', 'ef96b1fdeffc2d2b373824b74a6e2189', '2025-08-04 23:57:10', '2026-01-08 19:14:59', 'nacos', '27.189.32.117', '', '', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` VALUES (3, 'SapientiaCloud-EduPivot--system.yaml', 'DEFAULT_GROUP', 'pagehelper:\r\n  helper-dialect: mysql\r\n  reasonable: true\r\n  support-methods-arguments: true\r\n  params: count=countSql\r\n\r\nmybatis-plus:\r\n  type-aliases-package: com.dayz.sapientiacloud_edupivot.system.entity\r\n  mapper-locations: classpath:mapper/**/*.xml\r\n  configuration:\r\n    cache-enabled: false\r\n    map-underscore-to-camel-case: true\r\n  global-config:\r\n    db-config:\r\n      id-type: assign_id\r\n      update-strategy: not_null\r\n      logic-delete-field: deleted\r\n      logic-delete-value: 1\r\n      logic-not-delete-value: 0\r\n\r\nfeign:\r\n  client:\r\n    config:\r\n      default:\r\n        connectTimeout: 5000\r\n        readTimeout: 5000\r\n        loggerLevel: full\r\n  httpclient:\r\n    enabled: true\r\n\r\nspring:\r\n  jpa:\r\n    open-in-view: false\r\n    show-sql: true\r\n    hibernate:\r\n      ddl-auto: update', '63f71f1ecb3d3303b0f70ca818e225f8', '2025-08-05 00:14:29', '2025-08-05 00:14:29', 'nacos', '172.18.0.1', '', '', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` VALUES (4, 'SapientiaCloud-EduPivot--gateway.yaml', 'DEFAULT_GROUP', 'spring:\n  cloud:\n    gateway:\n      routes:\n        - id: SapientiaCloud-EduPivot--system\n          uri: lb://SapientiaCloud-EduPivot--system\n          predicates:\n            - Path=/api/system/**\n          filters:\n            - StripPrefix=2\n        - id: SapientiaCloud-EduPivot--auth\n          uri: lb://SapientiaCloud-EduPivot--auth\n          predicates:\n            - Path=/api/auth/**\n          filters:\n            - StripPrefix=2\n        - id: SapientiaCloud-EduPivot--minIO\n          uri: lb://SapientiaCloud-EduPivot--minIO\n          predicates:\n            - Path=/api/minIO/**\n          filters:\n            - StripPrefix=2\n        - id: SapientiaCloud-EduPivot--teacher\n          uri: lb://SapientiaCloud-EduPivot--teacher\n          predicates:\n            - Path=/api/teacher/**\n          filters:\n            - StripPrefix=2\n        - id: SapientiaCloud-EduPivot--student\n          uri: lb://SapientiaCloud-EduPivot--student\n          predicates:\n            - Path=/api/student/**\n          filters:\n            - StripPrefix=2\n        - id: SapientiaCloud-EduPivot--course\n          uri: lb://SapientiaCloud-EduPivot--course\n          predicates:\n            - Path=/api/course/**\n          filters:\n            - StripPrefix=2\n        - id: SapientiaCloud-EduPivot--classroom-ws\n          uri: lb:ws://SapientiaCloud-EduPivot--classroom\n          predicates:\n            - Path=/api/classroom/ws/**\n          filters:\n            - StripPrefix=2\n        - id: SapientiaCloud-EduPivot--classroom\n          uri: lb://SapientiaCloud-EduPivot--classroom\n          predicates:\n            - Path=/api/classroom/**\n          filters:\n            - StripPrefix=2\n        - id: SapientiaCloud-EduPivot--live-sse\n          uri: lb://SapientiaCloud-EduPivot--live\n          predicates:\n            - Path=/api/live/subscribe,/api/live/unsubscribe\n          filters:\n            - StripPrefix=1\n        - id: SapientiaCloud-EduPivot--live\n          uri: lb://SapientiaCloud-EduPivot--live\n          predicates:\n            - Path=/api/live/**\n          filters:\n            - StripPrefix=2\n        - id: SapientiaCloud-EduPivot--live-sse-alias\n          uri: lb://SapientiaCloud-EduPivot--live\n          predicates:\n            - Path=/api/celestial-hub/live/**\n          filters:\n            - StripPrefix=2\n        - id: SapientiaCloud-EduPivot--celestial-hub\n          uri: lb://SapientiaCloud-EduPivot--celestial-hub\n          predicates:\n            - Path=/api/celestial-hub/**\n          filters:\n            - StripPrefix=2\n\n  data:\n    redis:\n      host: ${REDIS_HOST}\n      port: ${REDIS_PORT}\n      password: ${REDIS_PASSWORD}\n      timeout: 6000ms\n      lettuce:\n        pool:\n          max-active: 8\n          max-wait: -1ms\n          max-idle: 8\n          min-idle: 0\n\nknife4j:\n  gateway:\n    enabled: true\n    strategy: discover\n    discover:\n      enabled: true\n      version: openapi3\n\ncache:\n  caffeine:\n    spec: maximumSize=500,expireAfterWrite=10m\n\nmanagement:\n  tracing:\n    enabled: true\n    sampling:\n      probability: 1.0\n  zipkin:\n    tracing:\n      endpoint: http://localhost:9411/api/v2/spans\n\nlogging:\n  level:\n    root: INFO\n    com.dayz: INFO\n\nREDIS_HOST: 127.0.0.1\nREDIS_PORT: 6379\nREDIS_USERNAME:\nREDIS_PASSWORD: zhaosheng123\n', '0935c71ab37bf3802729b6b0d17539a0', '2025-08-05 00:22:43', '2026-04-07 17:40:29', 'nacos', '27.189.37.170', '', '', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` VALUES (5, 'SapientiaCloud-EduPivot--minIO.yaml', 'DEFAULT_GROUP', 'minio:\n  config:\n    ip: ${MINIO_IP}\n    port: ${MINIO_PORT}\n    secure: ${MINIO_SECURE:false}\n    accessKey: ${MINIO_USERNAME}\n    secretKey: ${MINIO_PASSWORD}\n    bucketName: ${MINIO_BUCKET_NAME}\n    defaultBucketCode: USER_AVATAR\n    buckets:\n      - code: USER_AVATAR\n        bucketName: ${MINIO_BUCKET_USER_AVATAR:sapientiacloud-user-avatar}\n        description: 用户头像/证件照\n        access: PRIVATE\n        refreshCdnOnWrite: true\n        versioning:\n          enabled: true\n        lifecycle:\n          numVersions: 3\n        audit:\n          bucketLogging: true\n          notifyOnWrite: true\n      - code: COURSE_PUBLIC\n        bucketName: ${MINIO_BUCKET_COURSE_PUBLIC:sapientiacloud-course-public}\n        description: 课程公开课件/论坛封面\n        access: PUBLIC_READ\n        objectLockEnabled: true\n        objectLockMode: GOVERNANCE\n        objectLockRetentionDays: 7\n        versioning:\n          enabled: true\n        lifecycle:\n          numVersions: 10\n          transitionToInfrequentDays: 45\n        audit:\n          bucketLogging: true\n      - code: COURSE_PRIVATE\n        bucketName: ${MINIO_BUCKET_COURSE_PRIVATE:sapientiacloud-course-private}\n        description: 学员/教师私有资料\n        access: TOKEN_ONLY\n        versioning:\n          enabled: true\n        lifecycle:\n          transitionToInfrequentDays: 90\n          transitionToArchiveDays: 180\n        audit:\n          bucketLogging: true\n          objectTagging: true\n      - code: LIVE_PLAYBACK\n        bucketName: ${MINIO_BUCKET_LIVE_PLAYBACK:sapientiacloud-live-playback}\n        description: 直播录制\n        access: TOKEN_ONLY\n        versioning:\n          enabled: true\n        lifecycle:\n          transitionToInfrequentDays: 30\n          transitionToArchiveDays: 120\n        audit:\n          notifyOnWrite: true\n      - code: AI_QA_ASSET\n        bucketName: ${MINIO_BUCKET_AI_QA:sapientiacloud-ai-qa}\n        description: AI 问答资产\n        access: TOKEN_ONLY\n        versioning:\n          enabled: true\n        lifecycle:\n          expireAfterDays: 90\n        audit:\n          objectTagging: true\n          notifyOnWrite: true\n      - code: SYSTEM_NOTIFICATION\n        bucketName: ${MINIO_BUCKET_SYSTEM_NOTIFICATION:sapientiacloud-system-notification}\n        description: 系统通知中的图片、视频、附件资源\n        access: TOKEN_ONLY\n        versioning:\n          enabled: true\n        lifecycle:\n          expireAfterDays: 365\n        audit:\n          objectTagging: true\n\nspring:\n  servlet:\n    multipart:\n      enabled: true\n      max-file-size: 50MB\n      max-request-size: 100MB\n      file-size-threshold: 2MB\n\nMINIO_IP: 117.72.194.197\nMINIO_PORT: 31589\nMINIO_USERNAME: root\nMINIO_PASSWORD: zhaosheng123\nMINIO_BUCKET_NAME: sapientiacloud-edupivot\nMINIO_BUCKET_USER_AVATAR: sapientiacloud-user-avatar\nMINIO_BUCKET_COURSE_PUBLIC: sapientiacloud-course-public\nMINIO_BUCKET_COURSE_PRIVATE: sapientiacloud-course-private\nMINIO_BUCKET_LIVE_PLAYBACK: sapientiacloud-live-playback\nMINIO_BUCKET_AI_QA: sapientiacloud-ai-qa\nMINIO_BUCKET_SYSTEM_NOTIFICATION: sapientiacloud-system-notification\n\n# 服务器\n#MINIO_IP: 117.72.***.***(服务器地址)\n#MINIO_PORT: 31589\n#MINIO_USERNAME: root\n#MINIO_PASSWORD: zhaosheng123\n#MINIO_BUCKET_NAME: sapientiacloud-edupivot', 'afc777f053b6f4abd9b621d5d0e23f68', '2025-08-05 00:23:12', '2025-12-30 15:09:00', NULL, '111.11.15.6', '', '', NULL, NULL, NULL, 'text', NULL, '');
