INSERT INTO `config_info` VALUES (81, 'SapientiaCloud-EduPivot--celestial-hub.yaml', 'DEFAULT_GROUP', 'pagehelper:\n  helper-dialect: mysql\n  reasonable: true\n  support-methods-arguments: true\n  params: count=countSql\n\nmybatis-plus:\n  type-aliases-package: com.dayz.sapientiacloud_edupivot.celestial_hub.entity\n  mapper-locations: classpath:mapper/**/*.xml\n  configuration:\n    cache-enabled: false\n    map-underscore-to-camel-case: true\n  global-config:\n    db-config:\n      id-type: assign_id\n      update-strategy: not_null\n      logic-delete-field: deleted\n      logic-delete-value: 1\n      logic-not-delete-value: 0\n\nfeign:\n  client:\n    config:\n      default:\n        connectTimeout: 5000\n        readTimeout: 5000\n        loggerLevel: full\n  httpclient:\n    enabled: true\n\nspring:\n  mvc:\n    async:\n      request-timeout: -1\n  jpa:\n    open-in-view: false\n    show-sql: true\n    hibernate:\n      ddl-auto: update\n  data:\n    mongodb:\n      host: ${MONGODB_HOST}\n      port: ${MONGODB_PORT}\n      database: ${MONGODB_DATABASE}\n      username: ${MONGODB_USERNAME}\n      password: ${MONGODB_PASSWORD}\n      authentication-database: ${MONGODB_AUTH_DATABASE}\n      type-mapper: none\n  kafka:\n    bootstrap-servers: ${KAFKA_BOOTSTRAP_SERVERS:localhost:9092}\n    producer:\n      key-serializer: org.apache.kafka.common.serialization.StringSerializer\n      value-serializer: org.apache.kafka.common.serialization.StringSerializer\n      acks: all\n      retries: 3\n      enable-idempotence: true\n      compression-type: snappy\n      batch-size: 16384\n      linger-ms: 10\n      buffer-memory: 33554432\n    consumer:\n      group-id: chat-group\n      key-deserializer: org.apache.kafka.common.serialization.StringDeserializer\n      value-deserializer: org.apache.kafka.common.serialization.StringDeserializer\n      enable-auto-commit: false\n      auto-offset-reset: earliest\n    topic:\n      chat-request: chat-request-topic\n      chat-res