INSERT INTO `his_config_info` VALUES (4, 258, 'SapientiaCloud-EduPivot--gateway.yaml', 'DEFAULT_GROUP', '', 'spring:\n  cloud:\n    gateway:\n      routes:\n        - id: SapientiaCloud-EduPivot--system\n          uri: lb://SapientiaCloud-EduPivot--system\n          predicates:\n            - Path=/api/system/**\n          filters:\n            - StripPrefix=2\n        - id: SapientiaCloud-EduPivot--auth\n          uri: lb://SapientiaCloud-EduPivot--auth\n          predicates:\n            - Path=/api/auth/**\n          filters:\n            - StripPrefix=2\n        - id: SapientiaCloud-EduPivot--minIO\n          uri: lb://SapientiaCloud-EduPivot--minIO\n          predicates:\n            - Path=/api/minIO/**\n          filters:\n            - StripPrefix=2\n        - id: SapientiaCloud-EduPivot--teacher\n          uri: lb://SapientiaCloud-EduPivot--teacher\n          predicates:\n            - Path=/api/teacher/**\n          filters:\n            - StripPrefix=2\n        - id: SapientiaCloud-EduPivot--student\n          uri: lb://SapientiaCloud-EduPivot--student\n          predicates:\n            - Path=/api/student/**\n          filters:\n            - StripPrefix=2\n        - id: SapientiaCloud-EduPivot--course\n          uri: lb://SapientiaCloud-EduPivot--course\n          predicates:\n            - Path=/api/course/**\n          filters:\n            - StripPrefix=2\n        - id: SapientiaCloud-EduPivot--classroom\n          uri: lb://SapientiaCloud-EduPivot--classroom\n          predicates:\n            - Path=/api/classroom/**\n          filters:\n            - StripPrefix=2\n        - id: SapientiaCloud-EduPivot--live-sse\n          uri: lb://SapientiaCloud-EduPivot--live\n          predicates:\n            - Path=/api/live/subscribe,/api/live/unsubscribe\n          filters:\n            - StripPrefix=1\n        - id: SapientiaCloud-EduPivot--live\n          uri: lb://SapientiaCloud-EduPivot--live\n          predicates:\n            - Path=/api/live/**\n          filters:\n            - StripPrefix=2\n        - id: SapientiaCloud-EduPivot--live-sse-alias\n          uri: lb://SapientiaCloud-EduPivot--live\n          predicates:\n            - Path=/api/celestial-hub/live/**\n          filters:\n            - StripPrefix=2\n        - id: SapientiaCloud-EduPivot--celestial-hub\n          uri: lb://SapientiaCloud-EduPivot--celestial-hub\n          predicates:\n            - Path=/api/celestial-hub/**\n          filters:\n            - StripPrefix=2\n\n  data:\n    redis:\n      host: ${REDIS_HOST}\n      port: ${REDIS_PORT}\n      password: ${REDIS_PASSWORD}\n      timeout: 6000ms\n      lettuce:\n        pool:\n          max-active: 8\n          max-wait: -1ms\n          max-idle: 8\n          min-idle: 0\n\nknife4j:\n  gateway:\n    enabled: true\n    strategy: discover\n    discover:\n      enabled: true\n      version: openapi3\n\ncache:\n  caffeine:\n    spec: maximumSize=500,expireAfterWrite=10m\n\nmanagement:\n  tracing:\n    enabled: true\n    sampling:\n      probability: 1.0\n  zipkin:\n    tracing:\n      endpoint: http://localhost:9411/api/v2/spans\n\nlogging:\n  level:\n    root: INFO\n    com.dayz: INFO\n\nREDIS_HOST: 127.0.0.1\nREDIS_PORT: 6379\nREDIS_USERNAME:\nREDIS_PASSWORD: zhaosheng123\n', 'e69f3d30a686201ffc8d36b1fe02d57b', '2026-04-07 09:40:28', '2026-04-07 17:40:29', 'nacos', '27.189.37.170', 'U', '', '');
