INSERT INTO `his_config_info` VALUES (1, 260, 'application.yaml', 'DEFAULT_GROUP', '', 'spring:\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://${MYSQL_HOST}:${MYSQL_PORT}/${MYSQL_DATABASE}?rewriteBatchedStatements=true&characterEncoding=UTF-8&autoReconnect=true&failOverReadOnly=false&serverTimezone=Asia/Shanghai&allowMultiQueries=true\n    username: ${MYSQL_USERNAME}\n    password: ${MYSQL_PASSWORD}\n\n  data:\n    redis:\n      port: ${REDIS_PORT}\n      host: ${REDIS_HOST}\n      password: ${REDIS_PASSWORD}\n      database: 0\n      timeout: 6000ms\n      lettuce:\n        pool:\n          max-active: 8\n          max-wait: -1ms\n          max-idle: 8\n          min-idle: 0\n\n  cache:\n    type: redis\n    redis:\n      time-to-live: 1800000\n      cache-null-values: true\n      use-key-prefix: true\n      key-prefix: SapientiaCloud-EduPivot\n    caffeine:\n      spec: maximumSize=500,expireAfterWrite=10m\n\nknife4j:\n  enable: true\n  basic:\n    enable: true\n    username: ${KNIFE4J_USERNAME}\n    password: ${KNIFE4J_PASSWORD}\n\nmanagement:\n  tracing:\n    enabled: true\n    sampling:\n      probability: 1.0\n  zipkin:\n    tracing:\n      endpoint: http://localhost:9411/api/v2/spans\n\nlogging:\n  level:\n    root: INFO\n    com.dayz: INFO\n\n\nMYSQL_HOST: 127.0.0.1\nMYSQL_PORT: 3306\nMYSQL_USERNAME: root\nMYSQL_PASSWORD: zhaosheng123\nMYSQL_DATABASE: sapientiacloud_edupivot\nREDIS_HOST: 127.0.0.1\nREDIS_PORT: 6379\nREDIS_USERNAME:\nREDIS_PASSWORD: zhaosheng123\nKNIFE4J_USERNAME: admin\nKNIFE4J_PASSWORD: zhaosheng123', '0a38d47469123204faa6386b2b325738', '2026-04-11 11:50:47', '2026-04-11 19:50:47', 'nacos', '27.189.37.170', 'U', '', '');
